window.bootstrap = bootstrap

files.main.scss:
// Brand: two added theme colors, "brand" (teal) and "tertiary" (pink), and two
// removed with `null`, "info" and "secondary". Bootstrap generates a
// `.theme-*` class and the `--<theme>-*` root tokens for each entry of
// `$theme-colors`, so `.theme-brand` and `.theme-tertiary` exist and
// `.theme-info` and `.theme-secondary` don't. What still reads `--info-*` or
// `--secondary-*` points to a removed theme: `npm run audit-tokens` lists it.

@use "bootstrap/scss/bootstrap" with (
  $theme-colors: (
    "brand": (
      "base": var(--teal-500),
      "fg": light-dark(var(--teal-700), var(--teal-400)),
      "fg-emphasis": light-dark(var(--teal-800), var(--teal-200)),
      "bg": var(--teal-600),
      "bg-subtle": light-dark(var(--teal-100), var(--teal-900)),
      "bg-muted": light-dark(var(--teal-200), var(--teal-800)),
      "border": light-dark(var(--teal-300), var(--teal-600)),
      "focus-ring": light-dark(color-mix(in oklch, var(--teal-500) 50%, var(--bg-body)), color-mix(in oklch, var(--teal-500) 75%, var(--bg-body))),
      "contrast": var(--white)
    ),
    "tertiary": (
      "base": var(--pink-500),
      "fg": light-dark(var(--pink-600), var(--pink-400)),
      "fg-emphasis": light-dark(var(--pink-800), var(--pink-200)),
      "bg": var(--pink-500),
      "bg-subtle": light-dark(var(--pink-100), var(--pink-900)),
      "bg-muted": light-dark(var(--pink-200), var(--pink-800)),
      "border": light-dark(var(--pink-300), var(--pink-600)),
      "focus-ring": light-dark(color-mix(in oklch, var(--pink-500) 50%, var(--bg-body)), color-mix(in oklch, var(--pink-500) 75%, var(--bg-body))),
      "contrast": var(--white)
    ),
    "info": null,
    "secondary": null,
  ),
);

@use "custom";

